(()=>{const cut=u=>{let m;if(!u)return null;if(m=u.match(/(?:^|\/)img\/menu\/([^/?#]+)\.\w+/))return'/img/cut/'+m[1]+'.webp';if(m=u.match(/(?:^|\/)img\/(pick_\w+)\.\w+/))return'/img/cut/'+m[1]+'.webp';if(m=u.match(/items-images-production[^/]*\/files\/([0-9a-f]{40})\//))return'/img/cut/sq_'+m[1]+'.webp';return null};
const run=()=>document.querySelectorAll('.ci img,#top5 .c img,#enjoy .c img').forEach(i=>{const cs=i.getAttribute('src')||'';if(cs.includes('/img/cut/')||i.dataset.cx==='f')return;const c=i.closest('.ci,.c');const n=cut(cs||i.dataset.src);if(!n)return;const o=i.getAttribute('src');i.removeAttribute('srcset');i.onerror=()=>{i.onerror=null;i.dataset.cx='f';i.classList.remove('cut');c&&c.classList.remove('sb');i.src=o};i.src=n;i.classList.add('cut');c&&c.classList.add('sb')});
run();new MutationObserver(run).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['src']})})()
;
